scripts.divide_and_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Divide each A_i by B_i, keeping only whole-number part, then sum
    total = sum(A[i] // B[i] for i in range(len(A)))

    return float(total)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count pairs where earlier entry exceeds later entry
    count = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.iterate_formula:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    # Repeat K times: s = (A * s + B) % M
    for _ in range(K):
        s = (A * s + B) % M

    return float(s)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    # Compute N! mod MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

